export type ParsedGroupTradingCashV2Instruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    group: TAccountMetas[1];
    margin: TAccountMetas[2];
    quoteMint: TAccountMetas[3];
    vault: TAccountMetas[4];
    userToken: TAccountMetas[5];
    tokenProgram: TAccountMetas[6];
    btc: TAccountMetas[7];
    eth: TAccountMetas[8];
    guard: TAccountMetas[9];
    eventAuthority: TAccountMetas[10];
    program: TAccountMetas[11];
  };
  data: GroupTradingCashV2InstructionData;
};

export function parseGroupTradingCashV2Instruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedGroupTradingCashV2Instruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      group: getNextAccount(),
      margin: getNextAccount(),
      quoteMint: getNextAccount(),
      vault: getNextAccount(),
      userToken: getNextAccount(),
      tokenProgram: getNextAccount(),
      btc: getNextAccount(),
      eth: getNextAccount(),
      guard: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getGroupTradingCashV2InstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
